[CmdletBinding()]param([string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path,[string]$ReportPath='ES/Output/StaticReplay/es-abcd-worker-runtime.json')
$ErrorActionPreference='Stop'
$root=(Resolve-Path -LiteralPath $ProjectRoot).Path
Import-Module (Join-Path $root 'ES/Automation/ABCD/ESABCDFrameworkParity.psm1') -Force
$coverage=Get-ESABCDFrameworkCoverage;$requests=@()
foreach($f in @($coverage.frameworks)){foreach($c in @($f.capabilities)){$requests+=,[ordered]@{requestId=([Guid]::NewGuid().ToString('N'));frameworkId=$f.frameworkId;capabilityId=$c;payload=[ordered]@{scope='project';feedback='observed';reflection='bounded';count=2;max=3;used=0;output='';text='{}';maxLines=20;pruned=@();backtrack=$true;seed='worker';turns=2;stale=$false;score=0.7;expected='same';actual='same';trace=@('a');toolCalls=@('read')}}}}
